from lxml import etree
import re
t = etree.parse("alim_2025_11_03.xml")
for a in t.iter("ALIM"):
    d = {c.tag: (None if "missing" in c.attrib else (c.text or "")) for c in a}
    if d["alim_grp_code"].strip() == "00" or d["alim_ssgrp_code"].strip() == "0000":
        print("GROUP00", {k: v.strip() if v else v for k, v in d.items()})
for a in t.iter("ALIM"):
    d = {c.tag: (None if "missing" in c.attrib else (c.text or "")) for c in a}
    for k in ("alim_nom_eng", "alim_nom_fr", "alim_nom_sci"):
        v = d[k]
        if v and re.search(r"[\r\n\t]|  ", v.strip()):
            print(k, d["alim_code"].strip(), repr(v))
# ssssgrp == 000000 but ssgrp not 0000 counts; ssgrp 0000 but grp non 00
import collections
c = collections.Counter()
for a in t.iter("ALIM"):
    d = {c2.tag: (c2.text or "").strip() for c2 in a}
    c[(d["alim_grp_code"] == "00", d["alim_ssgrp_code"] == "0000", d["alim_ssssgrp_code"] == "000000")] += 1
print(c)
g = etree.parse("alim_grp_2025_11_03.xml")
for r in g.iter("ALIM_GRP"):
    d = {c2.tag: (c2.text or "").strip() for c2 in r}
    if d["alim_ssgrp_code"] == "0000" or d["alim_grp_code"] in ("00",) :
        print("GRPROW", d)
# check ss codes prefix consistency in alim
bad = 0
for a in t.iter("ALIM"):
    d = {c2.tag: (c2.text or "").strip() for c2 in a}
    if d["alim_ssgrp_code"] != "0000" and not d["alim_ssgrp_code"].startswith(d["alim_grp_code"]): bad += 1
    if d["alim_ssssgrp_code"] != "000000" and not d["alim_ssssgrp_code"].startswith(d["alim_ssgrp_code"]): bad += 1
print("prefix inconsistencies", bad)
EOF

